  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique identifier for the guest's device used for anonymous access
  /// tracking.
  device_fingerprint String

  /// Timestamp when the guest account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the guest account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the guest account was soft deleted. Null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions multi_user_todo_guest_sessions[]

  //----
  // INDEXES
  //----
  @@unique([device_fingerprint])
  @@index([created_at])
}

