  /// Optional start date.
  started_at DateTime? @db.Timestamptz

  /// Optional due date.
  due_at DateTime? @db.Timestamptz

  /// Completion timestamp. Null means incomplete, non-null means complete.
  completed_at DateTime? @db.Timestamptz

