import { IMultiUserTodoGuest } from "../../../../api/structures/IMultiUserTodoGuest";
import { postMultiUserTodoAuthGuestJoin } from "../../../../providers/postMultiUserTodoAuthGuestJoin";
import { postMultiUserTodoAuthGuestRefresh } from "../../../../providers/postMultiUserTodoAuthGuestRefresh";

@Controller("/multiUserTodo/auth/guest")
export class MultiusertodoAuthGuestController {
  /**
   * Register a new guest account for anonymous access to public endpoints. This operation creates a guest identity using the provided device fingerprint, which serves as a unique identifier for tracking anonymous users across sessions.
   *
   * The device fingerprint is stored with a uniqueness constraint to ensure each device maintains a single guest account. If a guest account already exists for the provided fingerprint, the operation returns the existing credentials rather than creating a duplicate.
   *
   * Upon successful registration, the system generates a new guest session with both access and refresh JWT tokens. The access token grants immediate authorization to protected endpoints, while the refresh token enables token renewal without re-registration. Session metadata including client IP, referrer, and current page URL are recorded for security auditing.
   *
   * Guest accounts support soft deletion via the deleted_at timestamp, allowing for account recovery within the retention period. This operation does not require prior authentication as it is the entry point for anonymous users.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Guest registration request containing device fingerprint for anonymous identification.
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor guest
   * @x-autobe-specification Create a new guest account using device fingerprint for anonymous access. Generate a unique guest ID and store the device fingerprint with uniqueness constraint. Create an initial guest session with access and refresh JWT tokens. Return the guest ID and tokens in the response. Handle duplicate device fingerprint by returning existing guest credentials. Validate device_fingerprint is provided and non-empty. Set session expiration based on configured guest session lifetime.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IMultiUserTodoGuest.IJoin,
  ): Promise<IMultiUserTodoGuest.IAuthorized> {
    try {
      return await postMultiUserTodoAuthGuestJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Renew an expired access token using a valid refresh token for continued guest session access. This operation enables guests to maintain their anonymous session without re-registering.
   *
   * The refresh token is validated for signature integrity and expiration status. The associated guest session is checked to ensure it exists in the database and has not exceeded its expiration timestamp. The guest account itself is verified to be active by confirming the deleted_at field is null.
   *
   * Upon successful validation, a new access token is generated with updated expiration. Optionally, a new refresh token may be issued if token rotation is enabled for enhanced security. The old refresh token is invalidated in rotation scenarios to prevent token reuse.
   *
   * This operation uses the refresh token itself as the authorization mechanism. Failed refresh attempts due to expired or invalid tokens return appropriate authentication errors, requiring the client to re-register via the join endpoint.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Token refresh request containing the refresh token for session renewal.
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor guest
   * @x-autobe-specification Refresh an expired access token using a valid refresh token. Validate the refresh token signature and expiration. Check that the associated guest session exists and is not expired. Verify the guest account is active (deleted_at is null). Generate a new access token and optionally a new refresh token. Return the new tokens in the response. Invalidate the old refresh token if token rotation is enabled. Handle expired refresh tokens by returning authentication error.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IMultiUserTodoGuest.IRefresh,
  ): Promise<IMultiUserTodoGuest.IAuthorized> {
    try {
      return await postMultiUserTodoAuthGuestRefresh({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

